script:
(function () {
  'use strict';
  // Simple interest: I = P x R x T and A = P(1 + R x T), with R the yearly rate (a monthly rate x 12)
  // and T in years (months / 12, days / 365). Rearranged to solve for any one unknown:
  //   P = A / (1 + RT),  R = (A/P - 1) / T,  T = (A/P - 1) / R.
  // Checked in Node (five.test.js): $10,000 at 6% for 5 years = $3,000 interest, $13,000 balance;
  // solving back from $13,000 returns $10,000, 6% and 5 years; $20,000 at 3% for 10 years = $26,000;
  // 1% a month for 18 months on $5,000 = $900; $1,000 at 5% for 73 days = $10.00;
  // compounded-yearly comparison $10,000 x 1.06^5 = $13,382.26.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var MODES = ['end', 'principal', 'rate', 'term'];
  var RADIOS = { end: 'siSolveEnd', principal: 'siSolvePrincipal', rate: 'siSolveRate', term: 'siSolveTerm' };
  var FIELDS = { end: 'siBalanceField', principal: 'siPrincipalField', rate: 'siRateField', term: 'siTermField' };
  var LABELS = { end: 'Total interest', principal: 'Principal needed', rate: 'Interest rate needed', term: 'Time needed' };
  var UNIT_YEARS = { years: 1, months: 1 / 12, days: 1 / 365 };
  var UNIT_NAMES = { years: ['year', 'years'], months: ['month', 'months'], days: ['day', 'days'] };
  var OUTPUTS = ['siAnswer', 'siEnd', 'siPrincipalOut', 'siInterest', 'siRateOut', 'siTermOut', 'siPerYear', 'siPerDay', 'siCompound'];

  // --- calc start
  function interest(p, rYear, tYears) { return p * rYear * tYears; }
  function solvePrincipal(a, rYear, tYears) { return a / (1 + rYear * tYears); }
  function solveRate(a, p, tYears) { return (a / p - 1) / tYears; }
  function solveTerm(a, p, rYear) { return (a / p - 1) / rYear; }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function fmt(x, digits) { return x.toFixed(digits).replace(/\.?0+$/, ''); }

  function mode() {
    for (var k = 0; k < MODES.length; k++) if (document.getElementById(RADIOS[MODES[k]]).checked) return MODES[k];
    return 'end';
  }

  function fail(msg) {
    var error = document.getElementById('siError');
    error.hidden = false;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { document.getElementById(id).textContent = '–'; });
    document.getElementById('siSchedule').innerHTML = '';
  }

  function update() {
    var solve = mode();
    MODES.forEach(function (m) { document.getElementById(FIELDS[m]).hidden = m === solve; });
    document.getElementById('siAnswerLabel').textContent = LABELS[solve];
    document.getElementById('siError').hidden = true;

    var a = num('siBalance'), p = num('siPrincipal'), rate = num('siRate'), term = num('siTerm');
    var rateUnit = document.getElementById('siRateUnit').value, termUnit = document.getElementById('siTermUnit').value;
    var rateMult = rateUnit === 'month' ? 12 : 1, unitYears = UNIT_YEARS[termUnit];
    var need = { end: [p, rate, term], principal: [a, rate, term], rate: [a, p, term], term: [a, p, rate] }[solve];
    if (need.some(isNaN)) return fail('Fill in every visible field with a number.');
    if (solve !== 'principal' && p <= 0) return fail('Enter a principal above $0.');
    if (solve !== 'end' && a <= 0) return fail('Enter an end balance above $0.');
    if (solve !== 'rate' && (rate < 0 || rate > 1000)) return fail('Enter an interest rate from 0 to 1,000%.');
    if (solve !== 'term' && (term <= 0 || term * unitYears > 1000)) return fail('Enter a term above 0 and no longer than 1,000 years.');
    if ((solve === 'rate' || solve === 'term') && a < p) return fail('The end balance must be at least the principal, since interest only adds to it.');

    var rYear = rate / 100 * rateMult, tYears = term * unitYears;
    if (solve === 'principal') p = solvePrincipal(a, rYear, tYears);
    else if (solve === 'rate') { rYear = solveRate(a, p, tYears); rate = rYear / rateMult * 100; }
    else if (solve === 'term') {
      if (rYear === 0) return fail(a === p ? 'At 0% the balance never changes, so any term works.' : 'At 0% interest the balance never grows. Enter a rate above 0.');
      tYears = solveTerm(a, p, rYear); term = tYears / unitYears;
      if (tYears > 1000) return fail('At this rate it would take more than 1,000 years.');
    }
    var i = interest(p, rYear, tYears), end = p + i;
    var compound = p * Math.pow(1 + rYear, tYears);
    if (![p, i, end, rate, term].every(isFinite) || Math.abs(end) > 1e15) return fail('That result is too large to show. Try smaller numbers.');

    var unitName = UNIT_NAMES[termUnit];
    var termText = fmt(term, 2) + ' ' + (Math.abs(term - 1) < 1e-9 ? unitName[0] : unitName[1]);
    var rateText = fmt(rate, 4) + '% per ' + rateUnit;
    var answer = { end: money.format(i), principal: money.format(p), rate: rateText, term: termText }[solve];
    document.getElementById('siAnswer').textContent = answer;
    document.getElementById('siEnd').textContent = money.format(end);
    document.getElementById('siPrincipalOut').textContent = money.format(p);
    document.getElementById('siInterest').textContent = money.format(i);
    document.getElementById('siRateOut').textContent = rateText + (rateUnit === 'month' ? ' (' + fmt(rYear * 100, 4) + '% a year)' : '');
    document.getElementById('siTermOut').textContent = termText;
    document.getElementById('siPerYear').textContent = money.format(p * rYear);
    document.getElementById('siPerDay').textContent = money.format(p * rYear / 365);
    document.getElementById('siCompound').textContent = isFinite(compound) && compound < 1e15 ? money.format(compound) : 'Too large to show';

    // Schedule: one row per term unit; switch to years when that would be more than 1,200 rows.
    var step = unitYears, count = term, head = unitName[0].charAt(0).toUpperCase() + unitName[0].slice(1);
    if (count > 1200) { step = 1; count = tYears; head = 'Year'; }
    document.getElementById('siPeriodHead').textContent = head;
    var rows = [], perPeriod = p * rYear * step, whole = Math.ceil(count - 1e-9);
    for (var k = 1; k <= whole && k <= 1200; k++) {
      var elapsed = Math.min(k, count) * step, total = p * rYear * elapsed, part = k > count + 1e-9;
      rows.push('<tr><td>' + k + (part ? ' (part)' : '') + '</td><td>' + money.format(part ? total - perPeriod * (k - 1) : perPeriod) +
                '</td><td>' + money.format(total) + '</td><td>' + money.format(p + total) + '</td></tr>');
    }
    document.getElementById('siSchedule').innerHTML = rows.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('siForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
